import os
import subprocess
import sys
from collections.abc import Iterator
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parents[2]


@pytest.fixture(scope="session")
def seed_dir(tmp_path_factory: pytest.TempPathFactory) -> Path:
    """The synthetic seed, from DIENSTPILOT_SEED_DIR or generated by the synthdata CLI."""
    given = os.environ.get("DIENSTPILOT_SEED_DIR")
    if given:
        return Path(given)
    out = tmp_path_factory.mktemp("seed") / "v1"
    subprocess.run(
        [sys.executable, "-m", "synthdata", "generate", "--out", str(out)], check=True, cwd=REPO
    )
    return out


@pytest.fixture(scope="session")
def database_url() -> Iterator[str]:
    """A Postgres database the tests may reset; skip when TEST_DATABASE_URL is not set."""
    url = os.environ.get("TEST_DATABASE_URL")
    if not url:
        pytest.skip("TEST_DATABASE_URL not set (needs a Postgres the tests may wipe)")
    env = {**os.environ, "DATABASE_URL": url}
    backend = REPO / "backend"
    subprocess.run(["alembic", "downgrade", "base"], check=True, cwd=backend, env=env)
    subprocess.run(["alembic", "upgrade", "head"], check=True, cwd=backend, env=env)
    yield url
